        description: "أدخل رقم الآيبان الجديد المكوّن من 23 رقمًا.",
        value: "AE07 0331 2345 6789 0123 456"
      }
    };

    const backdrop = document.getElementById("dialogBackdrop");
    const title = document.getElementById("dialogTitle");
    const description = document.getElementById("dialogDescription");
    const input = document.getElementById("editInput");
    const saveButton = document.getElementById("saveButton");
    const cancelButton = document.getElementById("cancelButton");
    let activeType = "";

    document.querySelectorAll("[data-edit]").forEach(button => {
      button.addEventListener("click", () => {
        activeType = button.dataset.edit;
        const copy = messages[activeType];
