    function closeDialog() {
      backdrop.classList.remove("open");
      activeType = "";
    }

    cancelButton.addEventListener("click", closeDialog);

    backdrop.addEventListener("click", event => {
      if (event.target === backdrop) closeDialog();
    });

    document.addEventListener("keydown", event => {
      if (event.key === "Escape" && backdrop.classList.contains("open")) closeDialog();
    });

    saveButton.addEventListener("click", () => {
      const value = input.value.trim();
      if (!value) {
        input.focus();
        return;
      }

      if (activeType === "profile") {
        const parts = value.split(/[,\n،]/);
        if (parts[0]) {
          document.querySelector(".profile-name").textContent = parts[0].trim();
        }
        if (parts[1]) {
          document.querySelector(".profile-email").textContent = parts[1].trim();
        }
      } else if (activeType === "phone") {
        document.querySelectorAll(".row-value")[0].textContent = value;
        messages.phone.value = value;
      } else if (activeType === "iban") {
        document.querySelectorAll(".row-value")[1].textContent = value;
        messages.iban.value = value;
      }

      closeDialog();
    });
